window.docContents[39].resolve({"/Improper-integrals/3___5-Abel-reweighting/#LMLF-___-DLMF-with-Lean--Improper-integrals--3___5-Abel-reweighting":{"contents":"Let F be the normalized primitive of g. Multiplication by the exponential weight\nexp (-h t) gives an improper integral whenever the weighted primitive is integrable and its\nboundary term tends to zero. Integration by parts identifies the value as h times the integral of\nthe weighted primitive.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Improper integrals","header":"3.5 Abel reweighting","id":"/Improper-integrals/3___5-Abel-reweighting/#LMLF-___-DLMF-with-Lean--Improper-integrals--3___5-Abel-reweighting"}});